def _prep_values(self, values: Optional[np.ndarray] = None) -> np.ndarray:
    """Convert input to numpy arrays for Cython routines"""
    if values is None:
        values = getattr(self._selected_obj, "values", self._selected_obj)

    # Ensure the data is coerced to float64
    if is_float_dtype(values.dtype):
        values = ensure_float64(values)
    elif is_integer_dtype(values.dtype):
        values = ensure_float64(values)
    elif needs_i8_conversion(values.dtype):
        raise NotImplementedError(
            "Operations for {action} for this dtype {dtype} are not implemented".format(
                action=self._window_type, dtype=values.dtype
            )
        )

    # Attempt to ensure float64 if not already done
    if not is_float_dtype(values.dtype):
        try:
            values = ensure_float64(values)
        except (ValueError, TypeError) as e:
            raise TypeError(f"Cannot handle this type -> {values.dtype}. Error: {str(e)}")

    # Always convert inf to nan
    values[np.isinf(values)] = np.NaN

    return values
